  "检查更新": "Check for updates",
  "上传经过校验的完整升级包到非活动槽，再由本机启动器安全切换。A/B 槽共用会话、设置和工作区数据；切换期间服务会短暂重启。": "Upload a validated full upgrade bundle to the inactive slot, then let the local launcher switch safely. A/B slots share sessions, settings, and workspace data; the service briefly restarts during the switch.",
  "A/B 软件槽": "A/B software slots",
  "刷新槽状态": "Refresh slot status",
  "等待宿主启动器同步镜像信息": "Waiting for the host launcher to sync image details",
  "选择 aide 软件升级包": "Choose an aide software upgrade bundle",
  "上传到非活动槽": "Upload to inactive slot",
  "正在读取 A/B 槽状态…": "Loading A/B slot status…",
  "升级包由发行流程生成，包含当前平台 Docker 镜像、manifest.json 和 SHA256SUMS。切换由随软件包安装的宿主启动代理执行，不会在容器内操作 Docker。": "Upgrade bundles are produced by the release workflow and contain the platform Docker image, manifest.json, and SHA256SUMS. A host-side agent included with the launcher performs the switch; the app container never controls Docker.",
