  "升级包已校验并暂存；手动激活后导入镜像并重启工作台": "Update package verified and staged. Manual activation imports the image and restarts the workbench.",
  "此版本已安装，可手动切换": "This version is installed and can be activated manually.",
  "未安装": "Not installed",
