  "手动激活槽 {0} 会导入该槽镜像并短暂重启 aide；用户数据卷保持共用。若新版本健康检查失败会自动回滚。继续？": "Manually activating slot {0} imports its image and briefly restarts aide. User data volumes remain shared, and a failed health check triggers automatic rollback. Continue?",
  "已提交切换请求，等待宿主启动器…": "Switch requested; waiting for the host launcher…",
  "切换已完成": "Switch complete",
  "仍在等待切换结果。服务重新就绪后可刷新槽状态。": "Still waiting for the switch result. Refresh slot status when the service is available again.",
  "A/B 槽状态已同步": "A/B slot status synchronized",
