  "升级包已安装到槽 {0}": "Upgrade bundle installed in slot {0}",
  "请先选择升级 ZIP 包": "Choose an upgrade ZIP first",
  "升级包上传失败": "Upgrade bundle upload failed",
  "正在切换：槽 {0}": "Switching to slot {0}",
  "切换请求已排队 {0} 秒，启动器尚未响应；请确认正在运行本机 start.command。": "Switch queued for {0}s; the launcher has not responded. Make sure the local start.command is running.",
  "选择 aide 完整发行 ZIP 包或升级 ZIP 包": "Choose a complete aide release ZIP or update ZIP",
  "选择完整发行包或升级 ZIP": "Choose complete release or update ZIP",
  "完整发行 ZIP 同时支持首次启动和应用内升级；macOS 自动解压后可直接选择解压文件夹。": "The complete release ZIP supports both first launch and in-app upgrades. If macOS extracts it automatically, select the extracted folder.",
  "完整发行包同时包含各平台启动器与一个校验过的 Docker 镜像。可用同一 ZIP 首次启动，也可上传到非活动槽；宿主启动代理负责切换，数据卷共用。": "The complete release bundle includes platform launchers and one verified Docker image. Use the same ZIP for first launch or upload it to an inactive slot; the host agent performs the switch and data volumes are shared.",
  "切换进度": "Switch progress",
  "所选目录中未找到同一文件夹内的 manifest.json、SHA256SUMS 和 Docker 镜像归档。若 macOS 已自动解压，请选择完整发行包文件夹；可忽略其中的启动器和工作区文件。": "Could not find manifest.json, SHA256SUMS, and the Docker image archive in one folder. If macOS extracted the ZIP, select the complete release folder; launcher and workspace files are ignored.",
  "所选目录有 {0} 个文件，但未找到完整的应用内升级包": "The selected folder has {0} files, but no complete in-app update bundle was found",
  "源码启动无需应用内升级；Release 完整发行包同时包含首次启动运行文件和 A/B 升级所需镜像。": "Source checkouts do not use in-app upgrades. The complete release bundle contains both first-run files and the image needed for A/B upgrades.",
  "所选 ZIP 不含可用于 A/B 升级的完整镜像。请选择 aide 完整发行包或应用内升级 ZIP；轻量启动器 ZIP 不含镜像。": "This ZIP does not contain a complete image for A/B upgrades. Choose a complete aide release or update ZIP; lightweight launcher ZIPs do not include the image.",
  "正在上传发行包": "Uploading release bundle",
  "{0} · {1} / {2} · {3}/s": "{0} · {1} / {2} · {3}/s",
  "校验完成，正在暂存": "Validation complete; staging bundle",
