  "完整运行与升级包（同一文件用于首次启动和 A/B 升级）": "Complete runtime and update bundle (same file for first launch and A/B upgrades)",
  "该 Release 没有完整运行与升级包。轻量启动器 ZIP 只用于联网安装，不能上传到 A/B 槽。": "This release has no complete runtime and update bundle. Lightweight launcher ZIPs are for online installation and cannot be uploaded to A/B slots.",
  "检查官方 Release 并下载适用于当前系统的启动包。启动新版后会复用原有 Docker 持久数据。": "Check official releases and download a launcher for your system. Starting the new version reuses the existing Docker data volumes.",
  "点击检查官方 Release": "Check official releases",
  "下载匹配系统的启动包，解压后运行其中的 start.command、start.ps1 或 start.sh。新版启动时会复用原有 aide 数据卷；当前服务不会在网页中被直接替换。": "Download the launcher for your system, extract it, and run start.command, start.ps1, or start.sh. The new launcher reuses aide's existing Docker data volumes; this page does not replace the running service directly.",
