  "选择要重置的范围。默认只重置设置项；更具破坏性的项需要你主动勾选。执行前会自动生成完整备份（含加密密钥与小秘历史）。": "Choose what to reset. Only settings are selected by default; more destructive scopes must be opted in. A full backup (encrypted secrets + voice history) is created before reset.",
