  "自动模式依次尝试本地离线和可用的联网神经音；都不可用或播放失败时直接回退浏览器合成。可手动选择浏览器合成。主聊天的机械朗读按钮不受此设置影响。": "Auto tries local offline and available online neural voices; if both are unavailable or playback fails, it falls back directly to browser TTS. Browser TTS can also be selected manually. The main chat read-aloud button is unaffected.",
