  "自动向AI提供当前工作目录、顶层文件、辅助资料来源和使用方式；不读取文件正文或自动连接远程来源。": "Automatically provides AI with the current working directory, top-level files, auxiliary sources, and usage; does not read file contents or auto-connect remote sources.",
  "读写 SQLite 数据库文件（参数化查询、事务、schema、导出）；零第三方依赖，基于 node:sqlite，默认只读": "Read/write SQLite database files (parameterized queries, transactions, schema, export); zero third-party deps, based on node:sqlite, read-only by default",
