  "常驻 UDP 通讯：绑定收包、发送、规则模拟应答、组播加入/离开；零第三方依赖，默认禁用，仅绑回环": "Persistent UDP communication: bind/receive, send, rule-based mock responses, multicast join/leave; zero deps, disabled by default, loopback only",
  "常驻守护插件（serialport）：真实串口读写 + 虚拟串口对(pty)用于测试/模拟设备；默认禁用，无设备映射": "Persistent daemon plugin (serialport): real serial port read/write + virtual serial pair (pty) for testing/simulating devices; disabled by default, no device mapping",
