  "实测写权限": "Test write access",
  "写权限实测会在该目录创建一个随机命名的临时文件并立即删除；若清理失败会明确报告。不会覆盖现有文件。继续？": "The write test creates a randomly named temporary file in this directory and immediately deletes it. Cleanup failures are reported. It will not overwrite existing files. Continue?",
  "写权限实测": "Write access test",
  "已在目标根目录创建并删除独占临时探针；写入与清理均通过": "A unique temporary probe was created and removed in the target root; write and cleanup both passed",
