  "检查中…": "Checking…",
  "检查只证明该时间点的具体步骤；只读检查不证明写权限。结果保留5分钟，重启清空。": "Results establish only the indicated step at that time. Read-only checks do not establish write access. Results expire after 5 minutes and reset on restart.",
