  "小秘会话记录的是对话历史，没有工作台任务成果。": "Assistant sessions contain conversation history, not workbench task outcomes.",
  "历史记录会话内容，调用记录展示工具返回，成果舱按任务整理文件、审批与证据。验证报告不等于独立验收。": "History contains conversation content; calls show tool returns; outcomes organize task files, approvals and evidence. Verification reports are not independent acceptance.",
