  "范围留空表示按来源默认扫描；添加一个或多个目录后仅索引所选目录及其子目录。": "Leave scopes empty to use each source's default. Add one or more directories to index only those directories and their descendants.",
  "优先路径在单批预算内先扫描；目录与文件都可添加。优先路径必须在已设置的范围中。": "Priority paths are scanned first within each batch. Add files or directories; each priority path must be within its configured scope.",
  "优先扫描会先检查目标目录，再继续普通目录；索引范围只限制知识索引，不改变文件查看或 AI 文件访问权限。": "Priority paths are checked before ordinary directories. Index scopes limit knowledge indexing only; they do not change file viewing or AI file access permissions.",
