  "地域须与密钥一致。模型只显示当前非实时接口兼容型号；音色自动同步官方目录，网络不可用时保留内置列表。语速调整播放倍率并保持音调。合成文本会发送至百炼并计费；失败默认保留文字，不切换机械声。": "The region must match your key. Only models compatible with this non-realtime API are listed. Voices sync from the official catalog, with bundled choices when unavailable. Speed changes playback rate while preserving pitch. Synthesis sends text to Model Studio and is billed. Failures preserve text without changing voices by default.",
