  "我会自动统筹交办的工作、跟进进展；空闲时也可以和我聊聊。": "I automatically coordinate assigned work and follow progress. We can also chat when things are quiet.",
  "工作统筹通过身份验证后自动运行，持续跟进交办任务、提醒和已授权消息；麦克风只控制收听。切换工作会话继续跟进，隐藏页面停止收听，锁屏或关闭页面停止统筹。工作优先，空闲时自然交流。": "Work coordination starts automatically after identity verification, following assigned tasks, reminders and authorized messages. The microphone only controls listening. Follow-up continues across work sessions. Hiding the page stops listening; locking or closing the page stops coordination. Work comes first, with friendly conversation when idle.",
