  "作用于助理交办的任务及其子任务，复用独立审批器判断具体命令和新文件提案并记录原因。无法确认授权、现有文件覆盖或受保护操作交由用户决定；不会代答业务澄清、指纹验证或消息邀请。关闭后遵循工作台原有审批模式。": "Applies to assistant-delegated tasks and their child tasks. The independent reviewer evaluates exact commands and new-file proposals and records reasons. Unclear authorization, overwriting existing files and protected operations return to you. It does not answer business clarifications, biometric prompts or message invitations. When off, the existing workbench approval mode applies.",
