  "{0} 份源码 · {1} 个声明 · {2} 条调用候选 · {3} 条类型绑定 · {4} 个未解析调用 · {5} 个未解析导入": "{0} source files · {1} declarations · {2} call candidates · {3} type bindings · {4} unresolved calls · {5} unresolved imports",
