  "黑洞 · 密集关联区域": "Black holes · Dense relationship regions",
  "黑洞外观依据：": "Black-hole visual references:",
  "黑洞外观借用近乎侧视的吸积盘观测线索：中央暗影遮住背景，紧邻暗影的细光环表示光子环；被引力透镜弯折的盘面可在暗影上下形成弧状像，盘的一侧会因相对论性多普勒增亮而更亮、更偏蓝，远离的一侧更暗、更偏红。NASA 的说明指出，黑洞本身不发光，暗影视直径约为事件视界直径的两倍，盘和透镜后的光才构成可见结构。星图用 Schwarzschild 零测地线转向点积分获得偏折角，以查找表插值控制逐帧开销，再通过几何薄透镜方程绘制主像、次像与连线偏折，并在独立 Canvas 光学层叠加。该强偏折映射比弱场点质量公式更适合靠近光子球的区域，但仍不是从相机到光源逐像素积分完整有限距离时空路径；不包含旋转 Kerr 度规、等离子折射或偏振。图谱密度只提供无量纲的视觉尺度，不提供真实质量或源距。这里的“黑洞”仍是关联密集区域的图谱标记，尺寸不代表黑洞质量、视界尺度或真实观测图像。": "Black-hole visuals borrow features of nearly edge-on accretion disks: a central shadow blocks the background, a thin nearby ring represents the photon ring, and gravitational lensing bends disk images into arcs above and below the shadow. Relativistic Doppler brightening makes one side brighter and bluer, and the receding side darker and redder. NASA explains that the hole itself emits no light; the apparent shadow diameter is about twice the event-horizon diameter, while the disk and lensed light form the visible structure. The map calculates deflection using turning-point integration of Schwarzschild null geodesics, interpolates a lookup table to control frame cost, and draws primary/secondary images and deflected links with a geometric thin-lens equation on a separate Canvas optical layer. This strong-deflection mapping is more suitable near the photon sphere than a weak-field point-mass formula, but it is not full per-pixel finite-distance spacetime ray tracing. It excludes Kerr rotation, plasma refraction and polarization. Graph density supplies only a dimensionless visual scale, not actual mass or source distance. These black holes remain dense-region graph markers; their sizes do not represent physical mass, event-horizon size or observational imagery.",
